<script setup lang="ts">
import { onHide, onLaunch, onShow } from '@dcloudio/uni-app'

function getToken(url) {
  const regex = /token=([^&#]+)/
  const match = url.match(regex)
  if (match && match[1]) {
    return match[1]
  } else {
    return null
  }
}

function getIsphone(url) {
  const regex = /isphone=([^&#]+)/
  const match = url.match(regex)
  if (match && match[1]) {
    return match[1]
  } else {
    return null
  }
}

// 判断当前是否处于 App 的真实入口页（首页为 pages/login）。
// 分享/深链会直接打开子页面路径，此时 URL 上的 token 不应被信任，避免会话被劫持。
function isEntryRoute(url) {
  try {
    const hashIndex = url.indexOf('#')
    const hashPart = hashIndex >= 0 ? url.slice(hashIndex + 1) : ''
    // hash 路由形如 #/pages/login?xxx；无 hash（history 模式或首页）也视为入口
    if (!hashPart || hashPart === '/') {
      return true
    }
    const routePath = hashPart.split('?')[0]
    return routePath === '/' || routePath === '/pages/login' || routePath === 'pages/login'
  } catch (e) {
    return true
  }
}

// 将 token / isphone 从地址栏 URL 中剥离（同时处理 # 前 query 与 # 后 query），
// 避免 token 停留在地址栏而被再次分享/复制，导致其他用户被登入他人账号。
function stripTokenFromUrl() {
  try {
    const url = window.location.href
    const hashIndex = url.indexOf('#')
    const beforeHash = hashIndex >= 0 ? url.slice(0, hashIndex) : url
    const hashPart = hashIndex >= 0 ? url.slice(hashIndex) : ''

    // 在完整 query 字符串上删除 token/isphone 参数，并清理残留的分隔符
    const stripParams = (query: string) => query
      // 删除形如 ?token=、&token=、?isphone=、&isphone= 的参数
      .replace(/([?&])(token|isphone)=[^&#]*/g, '$1')
      .replace(/^\?&/, '?')
      .replace(/[?&]{2,}/g, (m) => (m.includes('?') ? '?' : '&'))
      .replace(/[?&]$/, '')

    // # 前的 query 处理：在完整 beforeHash（保留 ?）上处理，避免参数在首位时匹配不到
    let newBefore = beforeHash
    if (beforeHash.includes('?')) {
      const path = beforeHash.slice(0, beforeHash.indexOf('?'))
      const query = beforeHash.slice(beforeHash.indexOf('?'))
      const stripped = stripParams(query)
      newBefore = path + (stripped && stripped !== '?' ? stripped : '')
    }

    let newHash = hashPart
    if (hashPart.includes('?')) {
      const hashPath = hashPart.slice(0, hashPart.indexOf('?'))
      const hashQuery = hashPart.slice(hashPart.indexOf('?'))
      const stripped = stripParams(hashQuery)
      newHash = hashPath + (stripped && stripped !== '?' ? stripped : '')
    }

    const newUrl = newBefore + newHash
    if (newUrl !== url) {
      window.history.replaceState(window.history.state, '', newUrl)
    }
  } catch (e) {
    // 剥离失败不影响主流程
  }
}

onLaunch((options) => {
  const href = window.location.href

  // 仅在真实入口页消费 URL 上的 token；分享/深链带过来的 token 一律忽略，
  // 防止其他用户通过分享链接携带 token 登录到分享者的账号。
  const token = isEntryRoute(href) ? getToken(href) : null
  console.log('token: ', token)
  uni.setStorageSync('urlToken', token)
  uni.setStorageSync('tokenConsumed', false)

  const isphone = getIsphone(href)
  console.log('isphone: ', isphone)
  uni.setStorageSync('isphone', isphone)

  // 读取后立即从地址栏移除 token / isphone，避免地址栏残留被二次分享后泄露登录态
  stripTokenFromUrl()

  // 重置弹窗状态，确保每次应用启动时都可能弹窗
  if (getApp()) {
    getApp().safetyNoticeShown = false
  }
})

onShow((options) => {
})

onHide(() => {
  // 应用隐藏时的逻辑
})

</script>

